  ('mem-05', 'memory', 1, -1.8, 0.2, 1, 28, 1, 'design-1', 'Classez mentalement 8, 3 et 11 par ordre croissant. Quelle est la deuxième valeur ?', '["3","8","11","9","5"]'::jsonb, null, 'L''ordre croissant est 3, 8, 11. La deuxième valeur est 8.', '["Le plus petit est 3, le plus grand 11.","8 se place entre les deux."]'::jsonb),
  ('mem-06', 'memory', 1, -0.9, 0.2, 2, 40, 2, 'design-1', 'Partez de 20. Retirez 6, doublez le résultat, puis retirez 8. Quel nombre obtenez-vous ?', '["16","18","20","22","28"]'::jsonb, null, '20 − 6 = 14, puis 14 × 2 = 28, puis 28 − 8 = 20.', '["20 − 6 = 14.","14 × 2 = 28.","28 − 8 = 20."]'::jsonb),
