  ('mem-09', 'memory', 1, -0.9, 0.2, 1, 38, 2, 'design-1', 'Dans le mot LANTERNE, quelle est la cinquième lettre ?', '["T","E","R","N","A"]'::jsonb, null, 'L-A-N-T-E-R-N-E : la cinquième lettre est E.', '["Compter : L(1), A(2), N(3), T(4), E(5)."]'::jsonb),
