  ('mem-11', 'memory', 1, 0, 0.2, 1, 50, 3, 'design-1', 'Partez de 7. Doublez, ajoutez 6, divisez par 4, puis retirez 2. Quel nombre obtenez-vous ?', '["2","3","4","5","6"]'::jsonb, null, '7 × 2 = 14, puis 14 + 6 = 20, puis 20 ÷ 4 = 5, puis 5 − 2 = 3.', '["7 × 2 = 14.","14 + 6 = 20.","20 ÷ 4 = 5.","5 − 2 = 3."]'::jsonb),
  ('mem-12', 'memory', 1, 0, 0.2, 3, 48, 3, 'design-1', 'Série : 5 - 9 - 2 - 8 - 4.

