  ('mem-19', 'memory', 1, 0.9, 0.2, 1, 60, 4, 'design-1', 'Dans le mot ANNIVERSAIRE, combien de fois la lettre A apparaît-elle ?', '["1","2","3","4","5"]'::jsonb, null, 'A-N-N-I-V-E-R-S-A-I-R-E : le A apparaît en première et en neuvième position, soit deux fois.', '["Parcourir le mot lettre à lettre.","Deux A seulement : rangs 1 et 9."]'::jsonb),
  ('mem-20', 'memory', 1, 0.9, 0.2, 1, 65, 4, 'design-1', 'Additionnez le rang de la lettre B et celui de la lettre E dans l''alphabet. Quelle lettre occupe le rang obtenu ?', '["F","G","H","I","J"]'::jsonb, null, 'B occupe le rang 2, E le rang 5. Leur somme vaut 7, soit la lettre G.', '["B = 2, E = 5.","2 + 5 = 7.","La septième lettre est G."]'::jsonb),
  ('mem-21', 'memory', 1, 1.8, 0.2, 2, 78, 5, 'design-1', 'Partez de 4. Élevez au carré, retirez 7, divisez par 3, puis ajoutez 5. Quel nombre obtenez-vous ?', '["6","7","8","9","10"]'::jsonb, null, '4² = 16, puis 16 − 7 = 9, puis 9 ÷ 3 = 3, puis 3 + 5 = 8.', '["4² = 16.","16 − 7 = 9.","9 ÷ 3 = 3.","3 + 5 = 8."]'::jsonb),
  ('mem-22', 'memory', 1, 1.8, 0.2, 1, 75, 5, 'design-1', 'Série : 8 - 3 - 5 - 9 - 2 - 7.

